/**
 * Generates integers from start to infinity, if end is
 * undefined; otherwise, generates integers from start
 * to end, not including end.
 *
 * @param start The integer to start at. Default is 0.
 * @param end An integer indicating the end of the range. Default is infinity.
 *
 * @internal
 */
export declare const range: (start?: number, end?: number | undefined) => Generator<number, void, unknown>;
